ValidationRule.errorConditionFormula:
OR(
    /* Case 1: Date selected but Date field is empty */
    AND(
        ISPICKVAL(Responded_By__c, "Date Option"),
        ISBLANK(Responded_Date__c)
    ),

    /* Case 2: Date NOT selected but Date field has value */
    AND(
        NOT(ISPICKVAL(Responded_By__c, "Date Option")),
        NOT(ISBLANK(Responded_Date__c))
    )
)
